package domain

import "github.com/google/uuid"

// NewID returns a new time-sortable entity ID (UUIDv7, RFC 9562) in its
// canonical lower-case string form. IDs generated by one process are
// strictly increasing.
func NewID() string {
	// uuid.NewV7 only fails when the system random source fails; since Go
	// 1.24 crypto/rand.Read never returns an error (it aborts the program
	// instead), so Must cannot panic in practice.
	return uuid.Must(uuid.NewV7()).String()
}
